// These are fixed race examples generated by the chat assistant during this
// design session. Helpers encode those records; they never simulate strategies.
type Row = [
  number,
  number,
  RaceBeat["racers"][number]["route"],
  RaceBeat["racers"][number]["status"],
  RaceBeat["racers"][number]["ability"],
  RacerId | null,
  string,
  string
];
function beat(
  title: string,
  narration: string,
  landmarkCue: string,
  rows: [Row, Row, Row]
): RaceBeat {
  return {
    title,
    narration,
    landmarkCue,
    racers: rows.map((row, index) => ({
      id: RACERS[index].id,
      progress: row[0],
      energy: row[1],
      route: row[2],
      status: row[3],
      ability: row[4],
      target: row[5],
      cue: landmarkCue,
      action: row[6],
      consequence: row[7]
    }))
  };
}
